namespace PKForge.App.Services;

/// <summary>
/// Player-selectable display language. Only UI text is translated: stored values, game
/// identifiers, file paths and menu action keys remain in their original form.
/// Missing translations safely fall back to English.
/// </summary>
public static class AppLanguage
{
    private const string Key = "ui_language";
    public static string Current => Preferences.Default.Get(Key, "en") == "es" ? "es" : "en";
    public static bool IsSpanish => Current == "es";
    public static string DisplayName => IsSpanish ? "Español" : "English";

    /// <returns>True when the selected language changed.</returns>
    public static bool Set(string language)
    {
        if (language is not ("en" or "es")) return false;
        if (Current == language) return false;
        Preferences.Default.Set(Key, language);
        return true;
    }

    /// <summary>Translate display-only text; never pass its result into business logic.</summary>
    public static string T(string text) =>
        IsSpanish && Spanish.TryGetValue(text, out var translation) ? translation : text;

